import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = [
        ('JLF4', 'KSN5'), ('HLXJ2B', 'GRVC13'), ('GRVC13', 'HXYL14'),
        ('GRVC13', 'QEEU10'), ('HXYL14', 'WLP2'), ('AYY4', 'SLVP3'),
        ('GRVC13', 'WSP3'), ('HLXJ2B', 'WSP3'), ('HLXJ2B', 'HXYL14'),
        ('HLXJ2B', 'QEEU10'), ('GRVC13', 'LURP8'), ('MLJP3', 'QEEU10'),
        ('UWW18', 'WLP2'), ('DKV1', 'DNKE5'), ('GRVC13', 'WLP2'),
        ('HXYL14', 'QEEU10'), ('IUQ15', 'UWW18'), ('LURP8', 'HXYL14'),
        ('QEEU10', 'WSP3'), ('SLVP3', 'JATA11B')
    ]

    # Build set of features to exclude due to correlation
    excluded = set()
    for a, b in correlated_pairs:
        if a in feats.ids and b in feats.ids:
            excluded.add(b)  # Keep first, remove second

    # Filter features
    keep_ids = [fid for fid in feats.ids if fid not in excluded]

    # Early exit if no features remain
    if not keep_ids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Create mapping from feature id to column index
    col_map = {fid: feats.column(fid) for fid in keep_ids if fid in feats.ids}

    # If we have no valid columns, return empty design
    if not col_map:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Get column indices for kept features
    keep_cols = list(col_map.values())

    # Check if we have valid column indices
    if not keep_cols:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Extract data matrix
    try:
        X = feats.x[:, keep_cols]
    except IndexError:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Calculate mean difference for each feature
    mean_diffs = []
    for i, fid in enumerate(keep_ids):
        if fid in feats.ids:
            idx = feats.column(fid)
            if idx < X.shape[1]:
                y0 = feats.y == 0
                y1 = feats.y == 1
                diff = np.mean(X[y1, i]) - np.mean(X[y0, i])
                mean_diffs.append(abs(diff))
            else:
                mean_diffs.append(0)
        else:
            mean_diffs.append(0)

    # Select top features by mean difference
    top_indices = np.argsort(mean_diffs)[::-1][:MAX_DRIVERS]
    selected_ids = [keep_ids[i] for i in top_indices if i < len(keep_ids)]

    # Check if any feature shows strong association (p < 0.05)
    drivers = []
    for fid in selected_ids:
        if fid in feats.ids:
            idx = feats.column(fid)
            if idx < X.shape[1]:
                try:
                    t_stat, p_val = stats.ttest_ind(X[feats.y==1, idx], X[feats.y==0, idx])
                    if p_val < 0.05:
                        drivers.append(fid)
                except:
                    continue

    # If no significant driver found, return empty design
    if len(drivers) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Create logistic regression model to assess interactions
    selected_cols = [feats.column(fid) for fid in selected_ids if fid in feats.ids and feats.column(fid) < X.shape[1]]

    if not selected_cols:
        return Design(drivers=(), columns=(), products=(), loadings={})

    X_selected = X[:, selected_cols]

    # Fit logistic regression
    clf = LogisticRegression(penalty='l1', solver='liblinear', C=0.1)
    clf.fit(X_selected, feats.y)

    # Get coefficients
    coefs = clf.coef_[0]

    # Select features with non-zero coefficients
    active_features = [selected_ids[i] for i, c in enumerate(coefs) if abs(c) > 1e-6]

    # For interaction terms, we'll use all pairwise combinations
    products = []
    for i, a in enumerate(active_features):
        for j, b in enumerate(active_features[i+1:], i+1):
            products.append((a, b))

    # Create loadings dictionary
    loadings = dict(zip(selected_ids, coefs))

    # Return final design
    return Design(
        drivers=tuple(drivers),
        columns=tuple(selected_ids),
        products=tuple(products),
        loadings=loadings
    )

